-- Phase 10 group authority. This migration is append-only and RPC-only.
begin;
alter table public.groups add column if not exists description text;
drop policy if exists groups_member_read on public.groups;
drop policy if exists groups_owner_insert on public.groups;
drop policy if exists groups_admin_update on public.groups;
drop policy if exists group_members_member_read on public.group_members;
drop policy if exists group_members_admin_write on public.group_members;
drop policy if exists group_invitations_member_read on public.group_invitations;
drop policy if exists group_invitations_admin_write on public.group_invitations;
revoke all on public.groups, public.group_members, public.group_invitations from public, anon, authenticated;

create table if not exists private.group_operation_receipts(
 actor_user_id uuid not null references auth.users(id) on delete cascade,
 operation_id uuid not null, operation_name text not null, request_hash text not null,
 response jsonb not null, created_at timestamptz not null default now(),
 primary key(actor_user_id,operation_id));
revoke all on private.group_operation_receipts from public,anon,authenticated;

create unique index if not exists group_one_owner_idx on public.group_members(group_id) where role='owner';
create or replace function private.group_member(g uuid,u uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$ select exists(select 1 from public.groups x join public.group_members m on m.group_id=x.id where x.id=g and x.deleted_at is null and m.user_id=u); $$;
create or replace function private.group_admin(g uuid,u uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$ select exists(select 1 from public.groups x join public.group_members m on m.group_id=x.id where x.id=g and x.deleted_at is null and m.user_id=u and m.role in('owner','admin')); $$;
create or replace function private.group_lock(a uuid,o uuid,n text,h text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare r jsonb; oh text; oname text; begin if a is null or o is null then raise exception 'operation id is required' using errcode='22023'; end if; perform pg_advisory_xact_lock(hashtextextended('group-op:'||a::text||':'||o::text,9010)); select response,request_hash,operation_name into r,oh,oname from private.group_operation_receipts where actor_user_id=a and operation_id=o for update; if r is not null and (oh<>h or oname<>n) then raise exception 'operation replay mismatch' using errcode='40001'; end if; return r; end; $$;
create or replace function private.group_record(a uuid,o uuid,n text,h text,r jsonb) returns void language sql security definer set search_path=pg_catalog,public,private as $$ insert into private.group_operation_receipts(actor_user_id,operation_id,operation_name,request_hash,response) values(a,o,n,h,r) on conflict(actor_user_id,operation_id) do nothing; $$;
create or replace function private.group_owner_invariant() returns trigger language plpgsql set search_path=pg_catalog,public,private as $$ declare g uuid; begin g:=case when tg_op='DELETE' then old.group_id else new.group_id end; if exists(select 1 from public.groups where id=g and deleted_at is null) and (select count(*) from public.group_members where group_id=g and role='owner')<>1 then raise exception 'group must have exactly one owner' using errcode='23514'; end if; if exists(select 1 from public.groups where id=g and deleted_at is null) and not exists(select 1 from public.group_members m join public.groups x on x.id=m.group_id where m.group_id=g and m.user_id=x.owner_user_id and m.role='owner') then raise exception 'group owner membership mismatch' using errcode='23514'; end if; if tg_op='DELETE' then return old; else return new; end if; end; $$;
drop trigger if exists group_owner_invariant on public.group_members;
create constraint trigger group_owner_invariant after insert or update or delete on public.group_members deferrable initially deferred for each row execute function private.group_owner_invariant();

create or replace function public.list_my_groups() returns table(group_id uuid,name text,owner_user_id uuid,type text,description text,event_create_policy text,role text) language sql stable security definer set search_path=pg_catalog,public,private as $$ select g.id,g.name,g.owner_user_id,g.type,g.description,g.event_create_policy,m.role from public.groups g join public.group_members m on m.group_id=g.id and m.user_id=auth.uid() where g.deleted_at is null order by g.updated_at desc; $$;
create or replace function public.get_group(p_group_id uuid) returns table(group_id uuid,name text,owner_user_id uuid,type text,description text,event_create_policy text,role text) language plpgsql security definer set search_path=pg_catalog,public,private as $$ begin if not private.group_member(p_group_id,auth.uid()) then raise exception 'group access denied' using errcode='42501'; end if; return query select g.id,g.name,g.owner_user_id,g.type,g.description,g.event_create_policy,m.role from public.groups g join public.group_members m on m.group_id=g.id and m.user_id=auth.uid() where g.id=p_group_id and g.deleted_at is null; end; $$;
create or replace function public.list_group_members(p_group_id uuid) returns table(group_id uuid,user_id uuid,display_name text,role text) language plpgsql stable security definer set search_path=pg_catalog,public,private as $$ begin if not private.group_member(p_group_id,auth.uid()) then raise exception 'group access denied' using errcode='42501'; end if; return query select m.group_id,m.user_id,coalesce(p.display_name,'利用者'),m.role from public.group_members m left join public.profiles p on p.user_id=m.user_id where m.group_id=p_group_id order by m.joined_at; end; $$;
create or replace function public.list_group_invites(p_group_id uuid) returns table(invite_id uuid,expires_at timestamptz,max_uses int,used_count int,revoked boolean) language plpgsql stable security definer set search_path=pg_catalog,public,private as $$ begin if not private.group_admin(p_group_id,auth.uid()) then raise exception 'admin required' using errcode='42501'; end if; return query select i.id,i.expires_at,i.max_uses,i.used_count,i.revoked_at is not null from public.group_invitations i where i.group_id=p_group_id order by i.created_at desc; end; $$;

create or replace function public.create_group(p_name text,p_type text default 'other',p_description text default null,p_event_create_policy text default 'member',p_operation_id uuid default null) returns table(group_id uuid,name text,owner_user_id uuid,type text,description text,event_create_policy text,role text) language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); i uuid; h text; r jsonb; begin if a is null then raise exception 'not authenticated' using errcode='42501'; end if; if length(trim(coalesce(p_name,'')))<1 or length(p_name)>120 or length(coalesce(p_description,''))>500 or p_type not in('friends','course','club','seminar','lab','part_time_job','other') or p_event_create_policy not in('member','admin','owner') then raise exception 'invalid group' using errcode='22023'; end if; h:=encode(extensions.digest(trim(p_name)||':'||p_type||':'||coalesce(trim(p_description),'')||':'||p_event_create_policy,'sha256'),'hex'); r:=private.group_lock(a,p_operation_id,'create_group',h); if r is not null then return query select (r->>'group_id')::uuid,r->>'name',(r->>'owner_user_id')::uuid,r->>'type',r->>'description',r->>'event_create_policy',r->>'role'; return; end if; insert into public.groups(owner_user_id,name,type,description,event_create_policy) values(a,trim(p_name),p_type,nullif(trim(p_description),''),p_event_create_policy) returning id into i; insert into public.group_members(group_id,user_id,role) values(i,a,'owner'); r:=jsonb_build_object('group_id',i,'name',trim(p_name),'owner_user_id',a,'type',p_type,'description',nullif(trim(p_description),''),'event_create_policy',p_event_create_policy,'role','owner'); perform private.group_record(a,p_operation_id,'create_group',h,r); return query select i,trim(p_name),a,p_type,nullif(trim(p_description),''),p_event_create_policy,'owner'; end; $$;
create or replace function public.update_group(p_group_id uuid,p_name text,p_type text,p_description text,p_event_create_policy text,p_operation_id uuid)
returns table(group_id uuid,name text,owner_user_id uuid,type text,description text,event_create_policy text,role text)
language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare a uuid:=auth.uid(); h text; r jsonb; current_group record;
begin
  if length(trim(coalesce(p_name,'')))<1 or length(p_name)>120 or length(coalesce(p_description,''))>500
     or p_type not in('friends','course','club','seminar','lab','part_time_job','other')
     or p_event_create_policy not in('member','admin','owner') then
    raise exception 'invalid group' using errcode='22023';
  end if;
  h:=encode(extensions.digest(jsonb_build_object('group_id',p_group_id,'name',trim(p_name),'type',p_type,'description',coalesce(trim(p_description),''),'event_create_policy',p_event_create_policy)::text,'sha256'),'hex');
  r:=private.group_lock(a,p_operation_id,'update_group',h);
  if r is not null then
    if not exists(select 1 from public.groups x join public.group_members m on m.group_id=x.id where x.id=p_group_id and x.deleted_at is null and x.owner_user_id=a and m.user_id=a and m.role='owner') then
      raise exception 'group authority changed' using errcode='42501';
    end if;
    return query select (r->>'group_id')::uuid,r->>'name',(r->>'owner_user_id')::uuid,r->>'type',r->>'description',r->>'event_create_policy',r->>'role'; return;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id::text,9010));
  if not exists(select 1 from public.groups x where x.id=p_group_id and x.owner_user_id=a and x.deleted_at is null) then raise exception 'owner required' using errcode='42501'; end if;
  update public.groups x set name=trim(p_name),type=p_type,description=nullif(trim(p_description),''),event_create_policy=p_event_create_policy,updated_at=now(),version=x.version+1 where x.id=p_group_id returning x.* into current_group;
  r:=jsonb_build_object('group_id',current_group.id,'name',current_group.name,'owner_user_id',current_group.owner_user_id,'type',current_group.type,'description',current_group.description,'event_create_policy',current_group.event_create_policy,'role','owner');
  perform private.group_record(a,p_operation_id,'update_group',h,r);
  return query select current_group.id,current_group.name,current_group.owner_user_id,current_group.type,current_group.description,current_group.event_create_policy,'owner';
end; $$;

create or replace function public.create_group_invite(p_group_id uuid,p_secret text,p_expires_at timestamptz,p_max_uses int,p_operation_id uuid) returns table(invite_id uuid,token text,expires_at timestamptz) language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); i uuid; d text; h text; r jsonb; inv record; begin if a is null then raise exception 'not authenticated' using errcode='42501'; end if; perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id::text,9010)); if not private.group_admin(p_group_id,a) or p_secret !~ '^[0-9a-fA-F]{64}$' or p_expires_at<=now() or p_expires_at>now()+interval '7 days' or p_max_uses is null or p_max_uses<1 or p_max_uses>100 then raise exception 'invalid invite' using errcode='22023'; end if; d:=encode(extensions.digest(lower(p_secret),'sha256'),'hex'); h:=p_group_id||':'||p_expires_at||':'||p_max_uses||':'||d; r:=private.group_lock(a,p_operation_id,'create_group_invite',h); if r is not null then select * into inv from public.group_invitations where id=(r->>'invite_id')::uuid and group_id=p_group_id for update; if not found or inv.revoked_at is not null or inv.expires_at<=now() or inv.used_count>=coalesce(inv.max_uses,1) or r->>'token_digest'<>d then raise exception 'operation replay mismatch' using errcode='40001'; end if; return query select inv.id,p_secret,inv.expires_at; return; end if; insert into public.group_invitations(group_id,token_hash,created_by,expires_at,max_uses) values(p_group_id,d,a,p_expires_at,p_max_uses) returning id into i; perform private.group_record(a,p_operation_id,'create_group_invite',h,jsonb_build_object('invite_id',i,'token_digest',d,'expires_at',p_expires_at)); return query select i,p_secret,p_expires_at; end; $$;
create or replace function public.preview_group_invite(p_token text) returns table(invite_id uuid,group_id uuid,group_name text,expires_at timestamptz,status text) language sql stable security definer set search_path=pg_catalog,public,private as $$ select i.id,i.group_id,g.name,i.expires_at,case when i.revoked_at is not null then 'revoked' when i.expires_at<=now() then 'expired' when i.used_count>=coalesce(i.max_uses,1) then 'exhausted' else 'active' end from public.group_invitations i join public.groups g on g.id=i.group_id and g.deleted_at is null where i.token_hash=encode(extensions.digest(lower(p_token),'sha256'),'hex'); $$;
create or replace function public.join_group_invite(p_token text,p_operation_id uuid) returns table(group_id uuid,name text,owner_user_id uuid,type text,description text,event_create_policy text,role text) language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); h text; r jsonb; i record; g record; gid uuid; begin if a is null or p_token !~ '^[0-9a-fA-F]{64}$' then raise exception 'invalid invite' using errcode='22023'; end if; h:=encode(extensions.digest(lower(p_token),'sha256'),'hex'); select x.group_id into gid from public.group_invitations x where x.token_hash=h; if gid is null then raise exception 'invite unavailable' using errcode='42501'; end if; perform pg_advisory_xact_lock(hashtextextended('group:'||gid::text,9010)); r:=private.group_lock(a,p_operation_id,'join_group_invite',h); select * into i from public.group_invitations where token_hash=h for update; select * into g from public.groups where id=gid and deleted_at is null for update; if not found or i.revoked_at is not null or i.expires_at<=now() or i.used_count>=coalesce(i.max_uses,1) then raise exception 'invite unavailable' using errcode='42501'; end if; if r is not null then if not exists(select 1 from public.group_members where group_id=g.id and user_id=a) then raise exception 'membership no longer active' using errcode='42501'; end if; return query select (r->>'group_id')::uuid,r->>'name',(r->>'owner_user_id')::uuid,r->>'type',r->>'description',r->>'event_create_policy',r->>'role'; return; end if; if exists(select 1 from public.group_members where group_id=g.id and user_id=a) then raise exception 'already a member' using errcode='PT409'; end if; insert into public.group_members(group_id,user_id,role) values(g.id,a,'member'); update public.group_invitations set used_count=used_count+1 where id=i.id; r:=jsonb_build_object('group_id',g.id,'name',g.name,'owner_user_id',g.owner_user_id,'type',g.type,'description',g.description,'event_create_policy',g.event_create_policy,'role','member'); perform private.group_record(a,p_operation_id,'join_group_invite',h,r); return query select g.id,g.name,g.owner_user_id,g.type,g.description,g.event_create_policy,'member'; end; $$;

create or replace function public.leave_group(p_group_id uuid,p_operation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); h text:=p_group_id::text; r jsonb; role text; begin r:=private.group_lock(a,p_operation_id,'leave_group',h); if r is not null then return; end if; perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id,9010)); select m.role into role from public.group_members m join public.groups g on g.id=m.group_id and g.deleted_at is null where m.group_id=p_group_id and m.user_id=a for update; if role is null or role='owner' then raise exception 'owner cannot leave' using errcode='22023'; end if; delete from public.group_members where group_id=p_group_id and user_id=a; if not found then raise exception 'member not found' using errcode='42501'; end if; perform private.group_record(a,p_operation_id,'leave_group',h,'{}'); end; $$;
create or replace function public.change_group_member_role(p_group_id uuid,p_user_id uuid,p_role text,p_operation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); h text:=p_group_id||':'||p_user_id||':'||p_role; r jsonb; begin r:=private.group_lock(a,p_operation_id,'change_group_member_role',h); if r is not null then return; end if; perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id,9010)); if not private.group_admin(p_group_id,a) or p_role not in('admin','member') or not exists(select 1 from public.group_members where group_id=p_group_id and user_id=p_user_id and role<>'owner') then raise exception 'role change denied' using errcode='42501'; end if; update public.group_members set role=p_role where group_id=p_group_id and user_id=p_user_id; if not found then raise exception 'member not found' using errcode='42501'; end if; perform private.group_record(a,p_operation_id,'change_group_member_role',h,'{}'); end; $$;
create or replace function public.remove_group_member(p_group_id uuid,p_user_id uuid,p_operation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); h text:=p_group_id||':'||p_user_id; r jsonb; begin r:=private.group_lock(a,p_operation_id,'remove_group_member',h); if r is not null then return; end if; perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id,9010)); if not private.group_admin(p_group_id,a) or exists(select 1 from public.group_members where group_id=p_group_id and user_id=p_user_id and role='owner') then raise exception 'member removal denied' using errcode='42501'; end if; delete from public.group_members where group_id=p_group_id and user_id=p_user_id; if not found then raise exception 'member not found' using errcode='42501'; end if; perform private.group_record(a,p_operation_id,'remove_group_member',h,'{}'); end; $$;
create or replace function public.transfer_group_ownership(p_group_id uuid,p_user_id uuid,p_operation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); h text:=p_group_id||':'||p_user_id; r jsonb; begin r:=private.group_lock(a,p_operation_id,'transfer_group_ownership',h); if r is not null then return; end if; perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id,9010)); if not exists(select 1 from public.groups where id=p_group_id and owner_user_id=a and deleted_at is null) or not exists(select 1 from public.group_members where group_id=p_group_id and user_id=p_user_id) or p_user_id=a then raise exception 'ownership transfer denied' using errcode='42501'; end if; update public.group_members set role='admin' where group_id=p_group_id and user_id=a; update public.group_members set role='owner' where group_id=p_group_id and user_id=p_user_id; update public.groups set owner_user_id=p_user_id,updated_at=now(),version=version+1 where id=p_group_id; perform private.group_record(a,p_operation_id,'transfer_group_ownership',h,'{}'); end; $$;
create or replace function public.revoke_group_invite(p_group_id uuid,p_invite_id uuid,p_operation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); h text:=p_group_id||':'||p_invite_id; r jsonb; begin perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id::text,9010)); r:=private.group_lock(a,p_operation_id,'revoke_group_invite',h); if r is not null then return; end if; if not private.group_admin(p_group_id,a) then raise exception 'admin required' using errcode='42501'; end if; update public.group_invitations set revoked_at=now() where id=p_invite_id and group_id=p_group_id; if not found then raise exception 'invite not found' using errcode='42501'; end if; perform private.group_record(a,p_operation_id,'revoke_group_invite',h,'{}'); end; $$;
create or replace function public.delete_group(p_group_id uuid,p_operation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare a uuid:=auth.uid(); h text:=p_group_id::text; r jsonb; begin r:=private.group_lock(a,p_operation_id,'delete_group',h); if r is not null then return; end if; perform pg_advisory_xact_lock(hashtextextended('group:'||p_group_id,9010)); if not exists(select 1 from public.groups where id=p_group_id and owner_user_id=a and deleted_at is null) then raise exception 'owner required' using errcode='42501'; end if; update public.groups set deleted_at=now(),updated_at=now(),version=version+1 where id=p_group_id; update public.group_invitations set revoked_at=coalesce(revoked_at,now()) where group_id=p_group_id; perform private.group_record(a,p_operation_id,'delete_group',h,'{}'); end; $$;

-- Re-declare join with qualified member columns so output-column names cannot
-- shadow table columns on PostgreSQL installations using strict PL/pgSQL rules.
create or replace function public.join_group_invite(p_token text,p_operation_id uuid) returns table(group_id uuid,name text,owner_user_id uuid,type text,description text,event_create_policy text,role text) language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare a uuid:=auth.uid(); h text; r jsonb; i record; g record; gid uuid;
begin
 if a is null or p_token !~ '^[0-9a-fA-F]{64}$' then raise exception 'invalid invite' using errcode='22023'; end if;
 h:=encode(extensions.digest(lower(p_token),'sha256'),'hex');
 r:=private.group_lock(a,p_operation_id,'join_group_invite',h);
 select x.group_id into gid from public.group_invitations x where x.token_hash=h;
 if gid is null then raise exception 'invite unavailable' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('group:'||gid::text,9010));
 select x.* into g from public.groups x where x.id=gid and x.deleted_at is null for update;
 if not found then raise exception 'group unavailable' using errcode='42501'; end if;
 if r is not null then
   if not exists(select 1 from public.group_members m where m.group_id=g.id and m.user_id=a) then raise exception 'membership no longer active' using errcode='42501'; end if;
   return query select (r->>'group_id')::uuid,r->>'name',(r->>'owner_user_id')::uuid,r->>'type',r->>'description',r->>'event_create_policy',r->>'role'; return;
 end if;
 select x.* into i from public.group_invitations x where x.token_hash=h for update;
 if not found or i.revoked_at is not null or i.expires_at<=now() or i.used_count>=coalesce(i.max_uses,1) then raise exception 'invite unavailable' using errcode='42501'; end if;
 if exists(select 1 from public.group_members m where m.group_id=g.id and m.user_id=a) then raise exception 'already a member' using errcode='PT409'; end if;
 insert into public.group_members(group_id,user_id,role) values(g.id,a,'member'); update public.group_invitations set used_count=used_count+1 where id=i.id;
 r:=jsonb_build_object('group_id',g.id,'name',g.name,'owner_user_id',g.owner_user_id,'type',g.type,'description',g.description,'event_create_policy',g.event_create_policy,'role','member'); perform private.group_record(a,p_operation_id,'join_group_invite',h,r);
 return query select g.id,g.name,g.owner_user_id,g.type,g.description,g.event_create_policy,'member';
end; $$;

